insert into public.diagnosis_references (slug, name, category, short_description, affected_plant_parts, growth_phase, first_symptoms, typical_causes, more_info)
values
  ('anthracnose', 'Antraknosa', 'Penyakit / jamur', 'Penyakit jamur dengan bercak cokelat cekung dan tidak beraturan, sering berpola seperti sasaran (cincin konsentris); dalam kondisi lembap dapat terbentuk massa spora yang lengket.', 'Daun; batang; kadang-kadang bunga', 'Semua fase, terutama saat cuaca lembap', 'Bercak cokelat kecil dan cekung pada daun atau batang', 'Kondisi lembap berkepanjangan, terutama pada budidaya luar ruang atau kelembapan udara dalam ruang yang tinggi; spora jamur menyebar melalui percikan air', ''),
  ('bakterielle-blattflecken-welke', 'Bercak daun bakteri / layu bakteri', 'Penyakit / jamur', 'Infeksi bakteri yang lebih jarang (bukan jamur), dengan bercak yang awalnya tampak seperti basah/translusen lalu berubah cokelat kehitaman, kadang dikelilingi halo kuning; tidak ada lapisan seperti tepung atau kapas sebagaimana pada jamur.', 'Daun', 'Semua fase', 'Bercak kecil translusen seperti basah pada daun', 'Bakteri masuk melalui luka (gigitan serangga atau pemangkasan saat pelatihan) atau percikan air; kondisi lembap mendukung perkembangbiakan dan penyebarannya', ''),
  ('blattlaeuse', 'Kutu daun', 'Hama', 'Serangga kecil berbentuk buah pir yang berkelompok pada tunas muda dan bagian bawah daun, serta mengeluarkan embun madu lengket yang sering mengundang jamur jelaga.', 'Tunas muda; bagian bawah daun; ketiak daun', 'Semua fase, terutama fase pertumbuhan vegetatif', 'Kelompok kecil serangga kehijauan hingga hitam di ujung tunas dan bagian bawah daun; permukaan daun sedikit lengket dan mengilap karena embun madu', 'Terbawa oleh tanaman yang terinfeksi atau kutu daun bersayap yang masuk dari luar; semut dapat memelihara dan menyebarkan kutu daun demi embun madunya', 'https://plantclue.com/diagnose/schaedlinge/; https://plantclue.com/blattlaeuse-cannabis-bekaempfen/; https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('bor-mangel', 'Kekurangan boron', 'Kekurangan nutrisi', 'Kekurangan mikronutrien yang jarang dan tidak mudah berpindah di dalam tanaman; terutama memengaruhi meristem apikal (titik tumbuh), yang dapat mati pada kekurangan berat.', 'Titik tumbuh (meristem apikal); daun baru', 'Fase pertumbuhan vegetatif', 'Daun baru sedikit melengkung atau terpuntir; tunas baru agak menebal dan rapuh', 'pH terlalu tinggi menghambat penyerapan boron; kekurangan nyata dalam substrat sangat jarang; pengapuran berlebihan pada substrat (kalsium berlebih tanpa penyeimbangan boron)', ''),
  ('bortoxizitaet', 'Toksisitas boron', 'Kelebihan nutrisi', 'Boron memiliki rentang paling sempit antara kekurangan dan toksisitas dibandingkan nutrisi lain; sedikit kelebihan saja dapat menyebabkan tepi daun tua menguning dan terbakar.', 'Tepi daun tua', 'Fase pertumbuhan vegetatif', 'Zona kuning di tepi daun tua, bermula dari ujung daun', 'Dosis sediaan boron berlebihan (kesalahan paling umum ialah konsentrasi racikan sendiri terlalu tinggi); penggunaan air sumur yang mengandung boron bersamaan dengan pemupukan boron tambahan', ''),
  ('breitmilben-russet-mites', 'Tungau lebar (tungau russet)', 'Hama', 'Tungau yang sangat kecil dan nyaris tak terlihat tanpa alat bantu; baru diketahui belakangan melalui penguningan menyebar, permukaan daun mengilap seperti kulit, dan tangkai daun yang melengkung ke bawah.', 'Daun baru dan titik tumbuh; tangkai daun', 'Semua fase; sering baru ditemukan pada akhir pembungaan', 'Permukaan daun baru agak mengilap dan hampir seperti kulit; tangkai daun sedikit melengkung ke bawah', 'Terbawa oleh klon atau tanaman induk yang terinfeksi (jalur penularan paling umum); ukurannya mikroskopis sehingga sulit dicegah dengan praktik kebersihan biasa', ''),
  ('bud-rot-botrytis', 'Busuk bunga (Botrytis)', 'Penyakit / jamur', 'Kapang abu-abu yang menyebar dari bagian dalam bunga yang padat; dari luar sering baru terlihat setelah bagian terinfeksi berubah cokelat/abu-abu dan menjadi lembek.', 'Bunga, bermula dari bagian dalam', 'Fase pembungaan, terutama pertengahan hingga akhir', 'Beberapa kuntum di dalam bunga berubah cokelat/abu-abu dan tampak agak cekung; pemeriksaan bagian dalam menunjukkan lapisan jamur abu-abu halus', 'Kelembapan udara tinggi dan bunga padat dengan ventilasi buruk; perubahan suhu yang menimbulkan kondensasi (lihat kondensasi/embun sebagai tahap awal); luka akibat hama (misalnya ulat penggerek bunga) menjadi jalan masuk', 'https://plantclue.com/grauschimmel-cannabis-botrytis-erkennen/; https://plantclue.com/cannabis-regenschutz-outdoor/; https://plantclue.com/cannabis-schimmel-regen/; https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('calciummangel', 'Kekurangan kalsium', 'Kekurangan nutrisi', 'Kekurangan unsur hara sekunder/mikro yang tidak mudah berpindah; karena itu daun dan tunas BARU terdampak lebih dahulu. Ciri khasnya bercak cokelat seperti karat dan ujung tunas baru yang berubah bentuk.', 'Daun baru dan titik tumbuh; bunga pada kekurangan lanjut', 'Fase pertumbuhan vegetatif; pembungaan (kekurangan berat meningkatkan risiko Botrytis)', 'Bercak kecil cokelat seperti karat pada daun baru bagian atas; titik tumbuh baru sedikit melengkung atau berubah bentuk', 'pH terlalu rendah menghambat penyerapan kalsium; air osmosis murni tanpa tambahan Cal-Mag; pertumbuhan terlalu cepat dengan pasokan kalsium yang tidak memadai; sistem hidroponik tanpa penambahan kalsium', 'https://plantclue.com/kalziummangel-cannabis/; https://plantclue.com/cannabis-blattspitzen-braun/; https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('calciumueberschuss-ueberkalkung', 'Kelebihan kalsium / pengapuran berlebihan', 'Kelebihan nutrisi', 'Kalsium berlebih (sering akibat pengapuran substrat berlebihan) menaikkan pH terlalu tinggi sehingga menghambat penyerapan mikronutrien seperti besi, mangan, seng, dan boron.', 'Daun baru; titik tumbuh', 'Fase pertumbuhan vegetatif', 'Klorosis ringan di antara tulang daun baru (akibat kekurangan Fe); pH substrat luar biasa tinggi (di atas 7,0)', 'Terlalu banyak kapur saat menyiapkan substrat (kapur dolomit/kapur taman berlebihan); penggunaan jangka panjang air keran sangat sadah dan kaya kalsium tanpa koreksi pH', ''),
  ('chlor-chloramin-wasser', 'Stres klorin/kloramin dalam air keran', 'Masalah pengairan', 'Air keran dengan kadar klorin atau kloramin tinggi (umum di perkotaan) dapat merusak rambut akar dan mikroorganisme bermanfaat di substrat, terlihat sebagai gangguan pertumbuhan menyeluruh yang tidak spesifik.', 'Akar; seluruh tanaman secara tidak langsung', 'Semua fase; sangat kritis pada substrat Living Soil', 'Pertumbuhan sedikit melambat tanpa penyebab lain yang terlihat; warna keseluruhan agak pucat meski pemupukan sudah tepat', 'Penggunaan langsung air keran tanpa diendapkan atau disaring di wilayah dengan pemberian klorin/kloramin tinggi; terutama relevan untuk kloramin yang tidak hilang hanya dengan diendapkan seperti klorin', 'https://plantclue.com/cannabis-living-soil-substrat/'),
  ('chlorophyll-heugeruch-curing-fehler', 'Bau klorofil/jerami (kesalahan pemeraman)', 'Masalah pembungaan/panen', 'Pengeringan terlalu cepat atau pemeraman yang tidak memadai menghambat penguraian sempurna klorofil dan senyawa tanaman lain; hasilnya berbau seperti jerami yang baru dipotong, bukan aroma khas varietas yang diharapkan.', 'Bunga yang sudah dikeringkan/diperam', 'Setelah pengeringan, selama pemeraman', 'Bunga kering berbau seperti rumput/jerami yang baru dipotong, bukan aroma terpena khas varietas', 'Pengeringan terlalu cepat (suhu terlalu tinggi atau kelembapan udara terlalu rendah) menghambat penguraian klorofil secara enzimatis; pemeraman tidak dilakukan atau terlalu singkat (disimpan dalam wadah kedap udara yang sesekali dibuka untuk pertukaran udara); panen saat kadar klorofil masih tinggi (misalnya akibat pemupukan nitrogen berat menjelang akhir, bukan pembilasan tepat waktu)', 'https://plantclue.com/cannabis-curing-fermentieren-anleitung/'),
  ('co2-mangel', 'Kekurangan CO₂', 'Stres lingkungan', 'Di tenda dalam ruang yang tertutup rapat tanpa pertukaran udara, kadar CO₂ dapat turun di bawah tingkat yang dibutuhkan untuk fotosintesis; terlihat sebagai pertumbuhan lambat secara umum meski kondisi lain optimal.', 'Seluruh tanaman', 'Semua fase, terutama di tenda sangat padat dengan ventilasi buruk dan kepadatan tanaman tinggi', 'Pertumbuhan secara umum lebih lambat meski cahaya, suhu, dan nutrisi optimal', 'Pertukaran udara masuk/keluar tidak ada atau tidak memadai di ruang tanam; kepadatan tanaman tinggi menghabiskan CO₂ lebih cepat daripada penggantiannya; ruangan tertutup rapat tanpa pasokan udara segar', ''),
  ('co2-ueberschuss', 'Kelebihan CO₂', 'Stres lingkungan', 'Hanya relevan pada pengayaan CO₂ aktif di ruang tertutup; konsentrasi terlalu tinggi dapat merusak daun dan juga membahayakan kesehatan orang di dalam ruangan.', 'Daun', 'Semua fase; hanya relevan jika CO₂ diperkaya secara aktif', 'Perubahan warna daun ringan dan menyebar tanpa pola jelas pada kadar CO₂ sangat tinggi', 'Pengaturan keliru atau kerusakan pada sistem pengayaan CO₂; pasokan CO₂ tanpa peningkatan intensitas cahaya yang sesuai (manfaat CO₂ memerlukan cahaya kuat)', ''),
  ('damping-off', 'Rebah kecambah (penyakit rebah semai)', 'Penyakit / jamur', 'Penyakit jamur yang khusus menyerang kecambah, menyebabkan bagian batang tepat di atas substrat menipis, tampak basah/translusen, lalu kecambah roboh dan mati.', 'Pangkal batang pada kecambah', 'Hanya fase kecambah', 'Bagian batang yang menipis dan tampak basah/translusen tepat di atas permukaan substrat', 'Substrat terlalu basah dan kurang aerasi selama fase kecambah; sirkulasi udara di bawah kubah kelembapan kurang, tanpa lubang ventilasi; media semai terkontaminasi', 'https://plantclue.com/cannabis-keimling-faellt-um/'),
  ('ec-zu-hoch', 'Nilai EC terlalu tinggi', 'Masalah pH / EC', 'Konsentrasi garam yang terlalu tinggi dalam larutan nutrisi atau substrat menghambat penyerapan air oleh akar melalui tekanan osmotik; terlihat sebagai daun layu meski substrat basah, disertai gejala terbakar.', 'Akar (utama); ujung daun; seluruh tanaman', 'Semua fase', 'Daun agak layu meski substrat cukup basah; warna daun hijau tua', 'Larutan nutrisi dibuat dengan konsentrasi total terlalu tinggi; tidak ada pembilasan berkala dengan air bersih; drainase substrat tidak memadai sehingga garam menumpuk', 'https://plantclue.com/ec-wert-cannabis-messen/'),
  ('echter-mehltau', 'Embun tepung', 'Penyakit / jamur', 'Penyakit jamur dengan lapisan putih seperti tepung pada permukaan daun; mudah terhapus saat disentuh, tetapi cepat muncul kembali.', 'Permukaan atas daun; bunga pada tahap lanjut', 'Semua fase', 'Bercak kecil putih seperti tepung pada permukaan atas daun', 'Sirkulasi udara buruk; jarak antartanaman terlalu rapat; kelembapan sedang hingga tinggi tanpa ventilasi memadai', 'https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('eisentoxizitaet', 'Toksisitas besi', 'Kelebihan nutrisi', 'Toksisitas yang jarang terjadi, biasanya akibat pH terlalu rendah sehingga besi menjadi terlalu mudah larut; tampak sebagai bercak perunggu hingga gelap pada daun tua.', 'Daun tua', 'Fase pertumbuhan vegetatif; pembungaan', 'Bercak kecil berwarna perunggu hingga cokelat kemerahan pada daun tua', 'pH terlalu rendah (di bawah 5,5) membuat besi dalam substrat tersedia berlebihan; dosis sediaan kelat besi sangat berlebihan', ''),
  ('eisenmangel', 'Kekurangan besi', 'Kekurangan nutrisi', 'Kekurangan mikronutrien yang tidak mudah berpindah, dengan klorosis antartulang daun; berbeda dari kekurangan magnesium karena mengenai daun BARU/atas. Sering disebabkan pH, bukan kekurangan besi sebenarnya.', 'Daun baru bagian atas; titik tumbuh', 'Fase pertumbuhan vegetatif; pembungaan', 'Area di antara tulang daun baru bagian atas berwarna kuning pucat hingga hampir putih; tulang daun tetap jelas hijau', 'pH terlalu tinggi menghambat penyerapan Fe (penyebab paling umum, bukan kekurangan Fe dalam substrat); zona akar dingin; penyiraman berlebihan menyebabkan kekurangan oksigen pada akar; kelebihan mangan menggeser besi', 'https://plantclue.com/eisenmangel-cannabis-chlorose/; https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('ernte-timing-fehler', 'Kesalahan waktu panen', 'Masalah pembungaan/panen', 'Panen terlalu dini atau terlambat sangat memengaruhi profil efek dan mutu; warna trikoma (putih susu dibandingkan kuning-jingga) merupakan indikator waktu yang paling andal.', 'Bunga; trikoma', 'Penentuan waktu panen pada akhir pembungaan', 'Panen terlalu dini: sebagian besar trikoma masih bening/transparan, belum putih susu; terlalu lambat: banyak trikoma kuning-jingga/cokelat, kadang putik mulai seluruhnya cokelat dan mengering', 'Warna trikoma tidak diperiksa atau diperiksa secara kurang akurat dengan lup/mikroskop; panen hanya mengikuti kalender/keterangan varietas, bukan kematangan sebenarnya; tekanan waktu dari luar (misalnya perubahan cuaca luar ruang) memaksa panen lebih cepat atau lambat dari waktu optimal', 'https://plantclue.com/cannabis-erntezeitpunkt-trichome-bestimmen/'),
  ('etiolation-vergeilung', 'Etiolasi (pertumbuhan memanjang berlebihan)', 'Stres cahaya', 'Cahaya yang kurang menyebabkan ruas batang memanjang secara tidak wajar, batang tipis, dan daun pucat; tanaman seolah “mencari” lebih banyak cahaya.', 'Seluruh tanaman, terutama batang dan ruas', 'Fase kecambah dan awal pertumbuhan vegetatif paling rentan', 'Jarak antarbuku daun luar biasa panjang; batang tipis dan lemah', 'Sumber cahaya terlalu lemah atau terlalu jauh dari tanaman; durasi penyinaran harian selama pertumbuhan vegetatif terlalu singkat; persaingan kuat dari tanaman sekitar yang lebih tinggi dan menaungi', 'https://plantclue.com/licht-cannabis-spektrum-beleuchtungsdauer/; https://plantclue.com/cannabis-saemling-spargelig-etioliert/'),
  ('falscher-mehltau', 'Embun bulu', 'Penyakit / jamur', 'Disebabkan patogen yang berbeda dari embun tepung; muncul bercak kuning hingga cokelat di permukaan atas daun, sedangkan lapisan jamur abu-abu/putih terbentuk di BAGIAN BAWAH daun.', 'Bagian bawah daun (lapisan jamur); permukaan atas daun (perubahan warna)', 'Semua fase, terutama saat kelembapan tinggi', 'Bercak kekuningan berbentuk bersudut di permukaan atas daun, sering dibatasi oleh tulang daun', 'Kelembapan udara tinggi berkepanjangan, terutama disertai suhu lebih dingin; sirkulasi udara buruk, khususnya di bagian bawah daun', 'https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('foxtailing', 'Foxtailing (bunga tumbuh bertingkat)', 'Masalah pertumbuhan dan pelatihan', 'Bunga tumbuh memanjang dan berlapis-lapis di ujung; dapat merupakan ciri genetik normal pada varietas tertentu atau respons stres terhadap panas/cahaya intens. Kondisi penyerta membedakan keduanya.', 'Bunga', 'Pertengahan hingga akhir pembungaan', 'Bunga tampak lebih runcing dan memanjang dari perkiraan, dengan bagian-bagian berlapis yang terlihat jelas', 'Karakter genetik varietas (beberapa galur dominan Sativa secara alami cenderung mengalami foxtailing); stres panas; cahaya terlalu intens mengenai bunga bagian atas', ''),
  ('fusarium-welke-oberirdisch', 'Layu Fusarium (bagian atas tanah)', 'Penyakit / jamur', 'Infeksi jamur sistemik pada jaringan pembuluh; berbeda dari busuk akar, tampak di bagian atas tanah sebagai layu progresif pada satu sisi cabang utuh dan warna cokelat khas pada penampang batang.', 'Jaringan pembuluh (xilem); batang; seluruh cabang', 'Semua fase', 'Satu atau beberapa cabang layu sementara bagian tanaman lain tampak sehat; tulang daun pada cabang yang layu sedikit berubah warna', 'Infeksi jamur melalui luka pada akar atau substrat/bahan tanaman terkontaminasi; stres (panas, kekurangan air) dapat mempercepat perkembangan penyakit', ''),
  ('fusarium-wurzelfaeule', 'Busuk akar Fusarium', 'Masalah akar', 'Jamur tanah yang menyerang akar dan batang bagian bawah; berbeda dari Pythium, sering disertai layu satu sisi pada beberapa cabang, bukan seluruh tanaman sekaligus.', 'Akar; batang bagian bawah; cabang tertentu', 'Semua fase', 'Beberapa cabang layu pada satu sisi sementara bagian tanaman lain tampak normal; sedikit perubahan warna di batang bawah', 'Substrat atau bahan stek terkontaminasi; luka akar (misalnya saat pemindahan pot) menjadi jalan masuk; kondisi stres melemahkan ketahanan tanaman', ''),
  ('gescheiterte-stecklingsbewurzelung', 'Stek gagal berakar', 'Masalah pertumbuhan dan pelatihan', 'Stek tidak membentuk akar dalam waktu lama meski tampak sehat; biasanya terkait teknik pemotongan, perlakuan hormon, atau kondisi iklim selama perakaran.', 'Pangkal stek; seluruh stek', 'Fase stek/perakaran', 'Setelah 1–2 minggu stek belum menunjukkan pertumbuhan baru atau bakal akar; layu ringan yang menetap meski berada dalam kubah kelembapan', 'Potongan dibuat miring, bukan rata, atau sudut/lokasi potong pada cabang induk keliru; hormon perakaran tidak digunakan atau diaplikasikan keliru; suhu substrat/udara terlalu rendah atau panas dasar kurang; tanaman induk kurang bugar (misalnya akibat HLVd, lihat [[hop-latent-viroid-hlvd]])', 'https://plantclue.com/cannabis-stecklinge-schneiden-und-bewurzeln/'),
  ('hermaphroditismus-stressbananen', 'Hermafroditisme (pisang stres)', 'Masalah pembungaan/panen', 'Stres atau faktor genetik memicu pembentukan struktur bunga jantan (“pisang”) pada tanaman yang sebenarnya betina; ada risiko penyerbukan sendiri dan pembentukan biji.', 'Bunga', 'Fase pembungaan', 'Struktur kecil kekuningan berbentuk pisang terlihat satu per satu di antara kelopak bunga betina', 'Stres lingkungan berkepanjangan (panas, kebocoran cahaya, kekurangan air, luka mekanis) selama pembungaan; kecenderungan genetik pada varietas/fenotipe yang tidak stabil; panen terlambat saat tanaman terlalu matang (sinyal penuaan alami)', ''),
  ('hitzestress', 'Stres panas', 'Stres lingkungan', 'Suhu terlalu tinggi, terutama jika cahaya terlalu dekat, menyebabkan daun menggulung ke atas seperti taco, ujung daun memucat, dan tanaman layu secara umum meski penyiraman cukup.', 'Seluruh tanaman, terutama daun bagian atas yang dekat dengan cahaya', 'Semua fase', 'Tepi daun menggulung ke atas seperti taco; sedikit layu meski substrat basah', 'Suhu ruang terlalu tinggi, sering akibat pendinginan/ventilasi keluar yang tidak memadai; lampu terlalu dekat dengan kanopi (menambah panas radiasi); sirkulasi udara tidak ada atau tidak memadai', 'https://plantclue.com/cannabis-blattspitzen-braun/; https://plantclue.com/cannabis-blaetter-rollen-sich-ein/; https://plantclue.com/cannabis-gelbe-blaetter-bluete/; https://plantclue.com/cannabis-krankheiten-erkennen/; https://plantclue.com/cannabis-temperatur-optimieren/'),
  ('hop-latent-viroid-hlvd', 'Viroid laten hop (HLVd)', 'Penyakit / jamur', 'Viroid yang sangat penting tetapi kerap diremehkan (“Dudding Disease”), menyebar secara sistemik melalui klon/tanaman induk dan menyebabkan penurunan kebugaran serta hasil secara bertahap tanpa satu gejala yang khas.', 'Seluruh tanaman, bersifat sistemik', 'Semua fase; gejala sering baru jelas setelah beberapa siklus perbanyakan', 'Pertumbuhan sedikit lebih lambat selama beberapa generasi klon; tunas sedikit lebih rapuh dan tipis daripada tanaman asal', 'Penularan melalui alat (gunting, pisau) antartanaman tanpa disinfeksi; penularan melalui kontak akar dalam sistem hidroponik atau penanaman rapat; memperoleh klon/genetika yang sudah terinfeksi', ''),
  ('kaliummangel', 'Kekurangan kalium', 'Kekurangan nutrisi', 'Kekurangan makronutrien yang mudah berpindah; biasanya tepi dan ujung daun menjadi kuning kecokelatan seperti terbakar, sementara bagian tengah daun tetap hijau.', 'Tepi dan ujung daun tua; seluruh tanaman pada tahap lanjut', 'Fase pertumbuhan vegetatif; terutama kritis saat pembungaan', 'Titik/bercak kuning di tepi daun tua; tepi daun sedikit melengkung ke atas', 'Kalium dalam pupuk terlalu sedikit, terutama saat pembungaan; pemupukan berlebihan dengan nutrisi lain menghambat penyerapan K (antagonisme); nilai EC keseluruhan terlalu tinggi; kelebihan kalsium atau magnesium menggeser kalium', 'https://plantclue.com/kaliummangel-cannabis-erkennen/; https://plantclue.com/cannabis-gelbe-blaetter-bluete/'),
  ('kaliumueberschuss', 'Kelebihan kalium', 'Kelebihan nutrisi', 'Kalium berlebih menghambat penyerapan kalsium dan magnesium (antagonisme); yang biasanya terlihat bukan kelebihan kalium itu sendiri, melainkan kekurangan Ca/Mg yang dipicunya.', 'Daun baru (akibat kekurangan Ca); daun tua (akibat kekurangan Mg)', 'Pembungaan (paling umum karena pupuk kaya K)', 'Klorosis di antara tulang daun tua seperti pada kekurangan Mg; sedikit perubahan bentuk daun baru seperti pada kekurangan Ca', 'Pupuk pembungaan diberikan terlalu pekat dengan dominasi K yang kuat; penggunaan booster PK saja terlalu lama tanpa keseimbangan pupuk dasar', ''),
  ('kaeltestress', 'Stres dingin', 'Stres lingkungan', 'Suhu terlalu rendah memperlambat metabolisme dan penyerapan nutrisi (terutama fosfor); sering terlihat sebagai tangkai daun ungu-kemerahan dan pertumbuhan lambat.', 'Seluruh tanaman, terutama tangkai daun dan batang', 'Semua fase, terutama malam yang dingin saat budidaya luar ruang', 'Tangkai daun sedikit berubah menjadi ungu-kemerahan; pertumbuhan sedikit melambat', 'Suhu ruang terlalu rendah, terutama malam hari atau tanpa pemanas; budidaya luar ruang saat embun beku dini atau malam musim gugur yang dingin; air siram dingin (lihat [[wassertemperatur-stress]]) sebagai faktor tambahan', 'https://plantclue.com/kaeltestress-cannabis-erkennen/; https://plantclue.com/cannabis-krankheiten-erkennen/; https://plantclue.com/cannabis-temperatur-optimieren/'),
  ('kondensation-taubildung-bluetenstaende', 'Kondensasi/pembentukan embun pada bunga', 'Suhu / kelembapan / VPD', 'Perubahan suhu (terutama malam hari atau pada budidaya luar ruang) menyebabkan kelembapan mengembun pada bunga; ini merupakan tahap langsung sebelum Botrytis dan perlu dibedakan sebagai risiko tersendiri dari busuk bunga yang sudah terjadi.', 'Bunga', 'Fase pembungaan', 'Tetes air/lapisan lembap terlihat pada dan di dalam bunga, terutama pagi hari atau setelah suhu turun', 'Perubahan suhu siang-malam yang besar; sirkulasi udara di dalam bunga padat tidak memadai; budidaya luar ruang dengan malam mendekati titik embun', 'https://plantclue.com/cannabis-regenschutz-outdoor/; https://plantclue.com/cannabis-schimmel-regen/'),
  ('larfy-popcorn-buds', 'Bunga kecil dan renggang (larfy/popcorn buds)', 'Masalah pembungaan/panen', 'Bunga kecil, renggang, dan kurang berkembang, terutama di bagian bawah tanaman yang kurang cahaya; biasanya akibat kekurangan cahaya, bukan penyakit tersendiri.', 'Bunga bagian bawah', 'Fase pembungaan', 'Bunga bagian bawah berkembang lebih lambat dan lebih renggang daripada bunga bagian atas', 'Intensitas cahaya di bagian bawah tanaman tidak memadai (ternaungi kanopi atas); kanopi tidak merata akibat kesalahan SCRoG/Mainlining (lihat [[ungleichmaessiges-blaetterdach-scrog-mainlining]]); kepadatan tanaman terlalu tinggi sehingga saling menaungi', ''),
  ('leaf-septoria', 'Bercak daun Septoria', 'Penyakit / jamur', 'Penyakit jamur dengan bercak bulat bertepi kuning-cokelat, biasanya pada daun tua bagian bawah; menyebar saat lembap dan menyebabkan daun rontok bertahap dari bawah ke atas.', 'Daun tua bagian bawah lebih dahulu', 'Semua fase, terutama di luar ruang saat cuaca lembap', 'Bercak bulat kecil kekuningan-cokelat dengan tepi agak lebih gelap pada daun bagian bawah', 'Cuaca lembap, terutama pada budidaya luar ruang; spora jamur dari tahun sebelumnya di tanah atau sisa tanaman terinfeksi; sirkulasi udara buruk di bagian bawah tanaman', ''),
  ('lichtverbrennung-light-burn', 'Daun terbakar cahaya (light burn)', 'Stres cahaya', 'Jarak lampu terlalu dekat atau intensitas cahaya terlalu tinggi membakar daun paling atas yang paling dekat dengan lampu; ciri khasnya, kerusakan terkonsentrasi di puncak kanopi.', 'Daun dan bunga paling atas yang paling dekat dengan lampu', 'Semua fase, terutama di bawah LED berintensitas tinggi', 'Ujung daun paling atas yang dekat lampu menguning hingga memucat; daun sedikit melengkung ke atas (mengarah ke cahaya)', 'Jarak antara lampu dan kanopi terlalu dekat; intensitas cahaya terlalu tinggi untuk fase pertumbuhan/toleransi varietas; pertumbuhan tidak merata sehingga beberapa pucuk tumbuh terlalu dekat dengan lampu', 'https://plantclue.com/cannabis-led-lichtverbrennung-erkennen/; https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('luftfeuchtigkeit-zu-niedrig', 'Kelembapan udara terlalu rendah', 'Suhu / kelembapan / VPD', 'Masalah iklim tersendiri, terlepas dari perhitungan VPD; udara sangat kering menyebabkan ujung daun terbakar dan substrat cepat kering, terutama berisiko bagi tanaman muda/stek.', 'Ujung daun; seluruh tanaman, terutama stek/kecambah', 'Semua fase; kritis selama fase stek/kecambah', 'Ujung daun sedikit kering dan rapuh tanpa gejala kekurangan nutrisi lain; substrat lebih cepat kering dari perkiraan', 'Udara ruang terlalu kering, terutama di ruang berpemanas pada musim dingin; tidak ada pelembap udara di ruang tanam; pada stek: tidak menggunakan kubah kelembapan/penutup selama perakaran', 'https://plantclue.com/luftfeuchtigkeit-cannabis-anbau/'),
  ('magnesiummangel', 'Kekurangan magnesium', 'Kekurangan nutrisi', 'Kekurangan unsur hara sekunder yang mudah berpindah, dengan gejala kekurangan paling khas: klorosis di antara tulang daun tua, sementara tulang daun tetap jelas hijau.', 'Daun kipas tua bagian bawah', 'Fase pertumbuhan vegetatif; pembungaan', 'Area di antara tulang daun bagian bawah menguning; tulang daun tetap jelas hijau', 'Magnesium dalam pupuk atau substrat terlalu sedikit; air terlalu sadah/lunak tanpa kandungan Mg; kelebihan kalium atau kalsium menghambat penyerapan Mg (antagonisme); pH terlalu rendah', 'https://plantclue.com/fleckige-cannabis-blaetter/; https://plantclue.com/cannabis-gelbe-blaetter-bluete/; https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('mangantoxizitaet', 'Toksisitas mangan', 'Kelebihan nutrisi', 'Toksisitas langka akibat pH terlalu rendah atau dosis campuran mikronutrien berlebihan; tampak sebagai bercak gelap dengan halo klorosis pada daun tua hingga sedang.', 'Daun bagian tengah hingga tua', 'Fase pertumbuhan vegetatif', 'Bercak kecil gelap dengan halo agak kekuningan pada daun bagian tengah', 'pH terlalu rendah; dosis sediaan kompleks mikronutrien berlebihan', ''),
  ('manganmangel', 'Kekurangan mangan', 'Kekurangan nutrisi', 'Kekurangan mikronutrien yang tidak mudah berpindah; sangat mirip dengan kekurangan besi (klorosis di antara tulang daun pada daun sedang/baru), sering disertai bintik cokelat kecil.', 'Daun bagian tengah hingga baru', 'Fase pertumbuhan vegetatif; pembungaan', 'Klorosis antartulang daun sedang/baru; bintik-bintik cokelat kecil tersebar di area klorosis', 'pH terlalu tinggi menghambat penyerapan Mn; kelebihan besi menggeser mangan (antagonisme); kekurangan Mn nyata dalam substrat sangat jarang', ''),
  ('minierfliegen', 'Lalat pengorok daun', 'Hama', 'Larva lalat kecil yang makan DI DALAM jaringan daun, meninggalkan lorong-lorong pucat berkelok khas (korokan) pada daun.', 'Bagian dalam daun', 'Semua fase', 'Garis/lorong tipis pucat yang berkelok terlihat di dalam helaian daun', 'Lalat pengorok dewasa meletakkan telur di jaringan daun; larva pengorok menetas darinya; lebih umum pada budidaya luar ruang atau dekat tanaman lain yang terinfeksi', ''),
  ('naehrstoffbrand-ueberduengung', 'Luka bakar nutrisi / pemupukan berlebihan', 'Kelebihan nutrisi', 'Dosis berlebihan beberapa nutrisi sekaligus; berbeda dari kekurangan satu unsur, ujung daun MUDA DAN TUA terbakar pada saat bersamaan.', 'Ujung daun di semua tingkat; tepi daun', 'Fase pertumbuhan vegetatif; pembungaan', 'Ujung terluar daun di beberapa tingkat berubah kuning hingga cokelat secara bersamaan; daun tampak hijau sangat tua', 'Konsentrasi total pupuk terlalu tinggi (EC terlalu tinggi); beberapa produk pupuk digunakan bersamaan tanpa mengurangi dosis masing-masing; pemupukan terlalu sering tanpa jeda penyiraman air bersih', 'https://plantclue.com/cannabis-ueberduengung/; https://plantclue.com/cannabis-blattspitzen-braun/'),
  ('ph-lockout', 'Lockout nutrisi akibat pH', 'Masalah pH / EC', 'pH berada jauh di luar rentang optimal sehingga beberapa nutrisi terhambat sekaligus; gejala utamanya adalah campuran gejala kekurangan yang tidak spesifik pada beberapa tingkat daun.', 'Beberapa tingkat daun sekaligus', 'Semua fase', 'Beberapa gejala kekurangan ringan yang berbeda muncul bersamaan, bukan satu pola yang jelas; pertumbuhan umum melambat meski pemupukan tepat', 'pH terus-menerus di luar 6,0–7,0 (tanah) atau 5,5–6,5 (hidroponik/kokos); pengukur pH tidak dikalibrasi atau rusak; pH substrat/larutan nutrisi tidak diperiksa secara berkala', 'https://plantclue.com/ph-wert-cannabis-einstellen/; https://plantclue.com/cannabis-blaetter-rollen-sich-ein/'),
  ('ph-zu-niedrig', 'pH terlalu rendah', 'Masalah pH / EC', 'Substrat/larutan nutrisi terlalu asam (di bawah 5,5–6,0) membuat mikronutrien seperti besi dan mangan terlalu tersedia (risiko toksisitas), sekaligus menghambat kalsium, magnesium, dan fosfor.', 'Seluruh tanaman; gejalanya bergantung pada nutrisi yang terhambat', 'Semua fase', 'Gejala campuran ringan akibat kekurangan Ca/Mg dan mungkin awal toksisitas Fe/Mn; pertumbuhan umum melambat', 'Penggunaan pupuk sangat asam tanpa penyangga pH; koreksi pH turun yang terlalu agresif tanpa pengukuran antara; substrat alami asam (misalnya gambut murni) tanpa penyeimbangan kapur', 'https://plantclue.com/ph-wert-cannabis-einstellen/'),
  ('phosphormangel', 'Kekurangan fosfor', 'Kekurangan nutrisi', 'Kekurangan makronutrien yang mudah berpindah, dengan warna ungu/merah khas pada tangkai dan bagian bawah daun; warna daun sering hijau tua hingga kebiruan.', 'Daun bagian bawah dan tengah; tangkai daun; batang', 'Fase pertumbuhan vegetatif; terutama kritis saat pembungaan (kebutuhan P meningkat)', 'Daun hijau tua hampir kebiruan; tangkai dan bagian bawah daun berubah merah/ungu; pertumbuhan sedikit melambat', 'Kandungan fosfor dalam pupuk terlalu rendah; zona akar terlalu dingin (di bawah 18 derajat, penyerapan P sangat bergantung suhu); pH di luar 6,0–7,0 (tanah) atau 6,0–6,5 (hidroponik); warna ungu bawaan genetik pada varietas tertentu (berisiko disalahartikan sebagai kekurangan)', 'https://plantclue.com/phosphormangel-cannabis-symptome/; https://plantclue.com/cannabis-gelbe-blaetter-bluete/; https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('photobleaching', 'Fotopemucatan (photobleaching)', 'Stres cahaya', 'Intensitas cahaya ekstrem menghancurkan klorofil lebih cepat daripada kemampuan tanaman membentuknya kembali; berbeda dari daun terbakar cahaya, jaringan tidak berubah cokelat melainkan memutih seluruhnya tanpa mati.', 'Daun dan bunga paling atas', 'Terutama fase pembungaan di bawah sistem LED sangat intens', 'Bagian daun paling atas tampak pucat keputihan, hampir transparan', 'Intensitas cahaya sangat tinggi (jauh di atas nilai PPFD yang disarankan untuk varietas/fase); umum pada LED berdaya tinggi modern dengan jarak yang tidak memadai', 'https://plantclue.com/licht-cannabis-spektrum-beleuchtungsdauer/'),
  ('pythium-wurzelfaeule', 'Busuk akar Pythium', 'Masalah akar', 'Patogen mirip jamur air yang membuat akar cokelat dan berlendir hingga membusuk dalam substrat yang terus basah dan kekurangan oksigen; bagian atas tanaman mendadak layu meski substrat basah.', 'Akar; seluruh tanaman (gejala lanjutan)', 'Semua fase, terutama sistem hidroponik/kokos', 'Tanaman sedikit layu meski substrat basah; pertumbuhan agak melambat', 'Substrat terus-menerus terlalu basah dan kekurangan oksigen; suhu larutan nutrisi dalam sistem hidroponik terlalu tinggi (di atas 24 derajat mendukung Pythium); peralatan/air terkontaminasi', 'https://plantclue.com/pythium-cannabis-wurzel/; https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('raupen-eulenfalter', 'Ulat / larva ngengat Noctuidae', 'Hama', 'Larva serangga berukuran lebih besar (terutama di luar ruang) memakan lubang tidak beraturan yang terlihat pada daun dan kadang langsung pada bunga; serangan bunga (“budworm”) sangat berisiko karena lorong gigitan menjadi jalan masuk Botrytis.', 'Daun; bunga jika diserang budworm', 'Semua fase, terutama budidaya luar ruang saat pembungaan', 'Lubang gigitan besar dan tidak beraturan pada daun; kotoran terlihat (butiran kecil gelap) pada daun atau bunga', 'Ngengat Noctuidae meletakkan telur, terutama pada budidaya luar ruang; tidak ada perlindungan jaring tanaman', ''),
  ('revegetation-reveg', 'Revegetasi (reveg)', 'Masalah pertumbuhan dan pelatihan', 'Tanaman yang sedang berbunga kembali ke pertumbuhan vegetatif akibat kesalahan pencahayaan (misalnya durasi terang tanpa sengaja diperpanjang); terlihat dari daun kipas baru yang normal tumbuh langsung dari bunga.', 'Bunga; tunas baru yang tumbuh dari bunga', 'Fase pembungaan', 'Beberapa daun kipas baru berbentuk normal tumbuh langsung dari bunga', 'Siklus gelap terputus tanpa sengaja (kebocoran cahaya) selama pembungaan; pengatur waktu keliru dan kembali ke siklus hari panjang; pergeseran hormonal akibat stres lingkungan ekstrem', ''),
  ('samenbildung-in-buds', 'Pembentukan biji di dalam bunga', 'Masalah pembungaan/panen', 'Akibat penyerbukan (oleh bunga jantan akibat stres pada tanaman sendiri, tanaman jantan yang terlewat, atau serbuk sari dari luar); terlihat dari biji yang berkembang di dalam kelopak, bukan massa bunga tanpa biji.', 'Bunga, di dalam kelopak', 'Pertengahan hingga akhir pembungaan', 'Beberapa kelopak bunga tampak agak bengkak/menebal dibandingkan kelopak yang tidak dibuahi', 'Bunga jantan akibat stres/hermafroditisme yang tidak terdeteksi pada tanaman sendiri; tanaman jantan di dekatnya tidak diketahui; serbuk sari terbawa dari luar, terutama pada budidaya luar ruang atau jendela terbuka', ''),
  ('sauerstoffmangel-wurzelzone', 'Kekurangan oksigen di zona akar', 'Stres lingkungan', 'Oksigen yang terlalu sedikit dalam substrat atau larutan nutrisi (sering karena pemadatan atau aerasi yang kurang) menghambat respirasi akar dan penyerapan nutrisi.', 'Akar; seluruh tanaman (gejala lanjutan)', 'Semua fase; kritis dalam sistem hidroponik/DWC', 'Pertumbuhan agak lambat meski pasokan nutrisi tepat; sedikit layu meski substrat basah', 'Substrat sangat padat atau berbutir terlalu halus tanpa pori udara (misalnya kandungan lempung terlalu tinggi); aerasi/pompa udara dalam sistem hidroponik/DWC tidak ada atau tidak memadai; penyiraman kronis berlebihan menggusur udara dari pori substrat', ''),
  ('schildlaeuse', 'Kutu sisik', 'Hama', 'Serangga menetap yang tersembunyi di bawah lapisan pelindung keras atau lunak; biasanya melekat pada batang dan tulang daun lalu mengisap cairan tanaman terus-menerus.', 'Batang; tulang daun; bagian bawah daun', 'Semua fase', 'Sisik kecil bulat hingga oval yang sedikit menonjol, berwarna cokelat atau abu-abu, di sepanjang batang atau tulang daun', 'Terbawa oleh tanaman terinfeksi; lebih umum pada tanaman induk/budidaya jangka panjang yang jarang diperbarui sepenuhnya', ''),
  ('schimmel-waehrend-trocknung', 'Jamur selama pengeringan', 'Masalah pembungaan/panen', 'Berbeda dari busuk bunga pada tanaman hidup, jamur ini berkembang setelah panen akibat kelembapan terlalu tinggi atau bunga digantung terlalu rapat selama pengeringan.', 'Bunga yang sudah dipanen dan sedang dikeringkan', 'Setelah panen, fase pengeringan', 'Bagian dalam bunga padat tertentu tetap terasa lembap/lunak saat pengeringan; area tertentu di ruang pengering sedikit berbau apak', 'Kelembapan ruang pengering terlalu tinggi (kisaran sasaran biasanya 45–55% RH); bunga digantung terlalu rapat tanpa jarak memadai; sirkulasi udara di ruang pengering kurang', 'https://plantclue.com/cannabis-trockenraum-einrichten/; https://plantclue.com/cannabis-trocknungsfehler-vermeiden/'),
  ('schlechte-trichom-entwicklung', 'Perkembangan trikoma buruk', 'Masalah pembungaan/panen', 'Secara keseluruhan bunga membentuk trikoma yang lebih sedikit dan lebih kecil daripada yang diharapkan dari genetiknya; biasanya kombinasi faktor cahaya, nutrisi, dan iklim pada akhir pembungaan, bukan satu penyebab tunggal.', 'Bunga; lapisan trikoma', 'Pertengahan hingga akhir pembungaan', 'Bunga tampak kurang “berkilau”/berselimut kristal dibandingkan gambar acuan varietas; trikoma tampak jarang atau lebih kecil dari perkiraan', 'Intensitas cahaya tidak memadai atau spektrum tidak tepat pada akhir pembungaan; suhu kurang optimal (suhu terlalu tinggi sering mengurangi produksi trikoma) pada akhir pembungaan; pasokan PK tidak memadai saat pembungaan utama; sifat genetik varietas (beberapa fenotipe memang menghasilkan lebih sedikit trikoma)', ''),
  ('schwefelmangel', 'Kekurangan sulfur', 'Kekurangan nutrisi', 'Kekurangan yang jarang dan relatif tidak mudah berpindah, dengan penguningan merata seperti kekurangan nitrogen tetapi pada daun BARU/atas, bukan bagian bawah; mudah tertukar.', 'Daun baru bagian atas; titik tumbuh', 'Fase pertumbuhan vegetatif', 'Daun baru paling atas sedikit memucat merata; pada awalnya tulang daun sedikit lebih hijau daripada helaian daun', 'Substrat atau air sangat rendah kandungan sulfur; penggunaan pupuk murni tanpa sulfur dalam jangka panjang; penyebab ini sangat jarang, biasanya singkirkan kemungkinan kekurangan lain terlebih dahulu', 'https://plantclue.com/schwefelmangel-cannabis-erkennen/'),
  ('spinnmilben', 'Tungau laba-laba', 'Hama', 'Arachnida kecil yang menyebabkan bintik-bintik halus pucat pada permukaan atas daun; pada serangan berat membuat jaring halus di antara daun dan tunas.', 'Permukaan atas dan bawah daun; ketiak daun pada serangan berat', 'Semua fase, terutama dalam kondisi hangat dan kering', 'Bintik-bintik halus pucat (titik putih/kekuningan kecil) tersebar di permukaan atas daun', 'Terbawa oleh tanaman terinfeksi, pakaian, atau udara luar; kondisi ruang hangat dan kering (kelembapan rendah) mendukung perkembangbiakan pesat', 'https://plantclue.com/spinnmilben-bekaempfen-cannabis/; https://plantclue.com/cannabis-weisse-punkte-blaetter/; https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('stickstoffmangel', 'Kekurangan nitrogen', 'Kekurangan nutrisi', 'Kekurangan makronutrien yang mudah berpindah. Tanaman memindahkan nitrogen dari daun tua ke daun baru, sehingga penguningan selalu bermula dari bawah lalu bergerak ke atas.', 'Daun bagian bawah; daun kipas tua; seluruh tanaman pada tahap lanjut', 'Fase pertumbuhan vegetatif; awal pembungaan (normal karena kebutuhan N menurun)', 'Daun paling bawah dan paling tua menguning merata; tulang daun ikut menguning (berbeda dari Mg/Fe); seluruh tanaman berwarna hijau muda', 'Pupuk nitrogen kurang atau tidak digunakan; substrat kehabisan nutrisi tanpa pemupukan tambahan; pH terlalu rendah menghambat penyerapan N; fase akhir pembungaan yang normal secara fisiologis', 'https://plantclue.com/outdoor-cannabis-probleme-erkennen/; https://plantclue.com/cannabis-mangel-erkennen-uebersicht/; https://plantclue.com/cannabis-gelbe-blaetter-bluete/; https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('stickstoffueberschuss', 'Kelebihan nitrogen', 'Kelebihan nutrisi', 'Nitrogen berlebih membuat daun hijau tua, mengilap, melengkung seperti cakar ke bawah, dan menunda awal pembungaan.', 'Seluruh tanaman; ujung daun', 'Fase pertumbuhan vegetatif; peralihan ke pembungaan', 'Daun sangat hijau tua dan hampir mengilap; ujung daun sedikit melengkung ke bawah (“cakar”)', 'Dosis N dalam pupuk pertumbuhan terlalu tinggi; terlambat beralih ke pupuk pembungaan; pemupukan berlebihan dengan pupuk nitrogen organik (guano, serutan tanduk)', 'https://plantclue.com/cannabis-krallenblaetter-ursache/'),
  ('thripse', 'Trips', 'Hama', 'Serangga kecil ramping memanjang yang mengisap permukaan daun dan meninggalkan bekas gigitan keperakan mengilap disertai titik kotoran hitam kecil.', 'Permukaan atas daun; bunga pada serangan berat', 'Semua fase', 'Garis/bercak halus keperakan mengilap di permukaan atas daun; titik kotoran hitam kecil tersebar di daun', 'Terbawa oleh tanaman terinfeksi atau masuk melalui jendela terbuka/dari area luar; kondisi hangat dan kering mendukung perkembangbiakan', 'https://plantclue.com/diagnose/schaedlinge/; https://plantclue.com/thripse-cannabis-erkennen/; https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('topping-fim-trainingsfehler', 'Kesalahan pelatihan Topping/FIM', 'Masalah pertumbuhan dan pelatihan', 'Topping atau FIM yang dilakukan keliru (misalnya terlalu terlambat atau titik potong salah) menyebabkan pola tumbuh yang tidak diinginkan, seperti hanya satu tunas baru alih-alih dua atau pemulihan tertunda.', 'Titik potong; tunas baru di titik potong', 'Tepat setelah tindakan, fase pertumbuhan vegetatif', 'Hanya SATU tunas baru terbentuk di titik potong, bukan dua yang diharapkan (pada topping), atau tidak ada tunas; respons tertunda lebih dari 1–2 minggu', 'Potongan terlalu rendah/tinggi atau pada buku daun yang salah; FIM tidak dilakukan dengan tepat (jaringan yang dibuang terlalu banyak/sedikit); topping dilakukan setelah pembungaan dimulai; tanaman terlalu muda/lemah untuk tindakan tersebut', ''),
  ('trainingsstress', 'Stres akibat pelatihan tanaman (LST/Topping/defoliasi keliru)', 'Stres lingkungan', 'Teknik pelatihan yang dilakukan dengan intensitas berlebihan atau pada waktu yang salah (terlalu banyak membuang daun, topping saat berbunga, LST terlalu agresif) membebani tanaman sementara.', 'Seluruh tanaman; bagian yang dipotong/ditekuk', 'Langsung setelah tindakan pelatihan, semua fase', 'Bagian yang ditangani sedikit layu segera setelah tindakan; pertumbuhan berhenti sementara', 'Defoliasi terlalu berat (lebih dari 20–30% massa daun sekaligus); topping/FIM terlambat (setelah pembungaan dimulai) atau terlalu sering; LST terlalu agresif tanpa jeda pemulihan yang cukup antarpembengkokan', 'https://plantclue.com/cannabis-stecklinge-schneiden-und-bewurzeln/'),
  ('transplantationsschock', 'Syok transplantasi', 'Masalah akar', 'Stres sementara setelah pemindahan pot akibat akar terluka dan kondisi berubah; tampak sebagai layu singkat/pertumbuhan terhenti, lalu pulih sendiri dalam beberapa hari.', 'Seluruh tanaman', 'Langsung setelah pemindahan pot, semua fase pertumbuhan', 'Sedikit layu merata segera setelah pemindahan pot; pertumbuhan berhenti selama beberapa hari', 'Akar terluka saat pemindahan pot; perubahan mendadak pada substrat, cahaya, atau iklim saat pemindahan; lonjakan ukuran pot terlalu besar (misalnya langsung dari pot sangat kecil ke sangat besar)', 'https://plantclue.com/cannabis-umtopfen/'),
  ('trauermuecken', 'Agas jamur (lalat hitam media tanam)', 'Hama', 'Lalat hitam kecil yang larvanya memakan rambut akar dan bahan organik di substrat yang lembap; lalat dewasa sering beterbangan di sekitar tanaman, sedangkan kerusakan larva tampak sebagai gangguan pertumbuhan menyeluruh.', 'Rambut akar; permukaan substrat', 'Semua fase, terutama saat substrat terus lembap', 'Lalat hitam kecil beterbangan saat penyiraman atau substrat disentuh; pertumbuhan sedikit melambat', 'Permukaan substrat terus terlalu lembap; bahan organik (misalnya bagian tanaman mati) di dalam substrat menjadi sumber makanan larva', 'https://plantclue.com/trauermuecken-cannabis-larven-bekaempfen/; https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('ueberwaesserung', 'Penyiraman berlebihan', 'Masalah pengairan', 'Penyiraman terlalu sering atau terlalu banyak mengusir oksigen dari substrat; terlihat sebagai daun terkulai dan lemas meski substrat basah, sering disertai permukaan daun lebih gelap dan agak membengkak.', 'Akar; seluruh tanaman', 'Semua fase', 'Daun terkulai dan lemas meski substrat basah; substrat terasa terus basah dan hampir tidak mengering', 'Penyiraman terlalu sering tanpa mempertimbangkan pengeringan substrat yang sebenarnya; pot terlalu besar dibandingkan ukuran tanaman sehingga lebih lama menahan air; drainase substrat/pot buruk', 'https://plantclue.com/cannabis-ueberwaessert-was-tun/; https://plantclue.com/cannabis-indoor-anbau-anleitung/; https://plantclue.com/cannabis-blattspitzen-braun/; https://plantclue.com/cannabis-blaetter-rollen-sich-ein/; https://plantclue.com/cannabis-gelbe-blaetter-bluete/'),
  ('ungleichmaessiges-blaetterdach-scrog-mainlining', 'Kanopi tidak merata akibat kesalahan SCRoG/Mainlining', 'Masalah pertumbuhan dan pelatihan', 'Kesalahan membentuk jaring SCRoG atau membagi cabang dengan Mainlining menyebabkan distribusi cahaya tidak merata; sebagian bunga berkembang berlebihan, sedangkan lainnya tertinggal dalam naungan.', 'Bunga bagian bawah/ternaungi; struktur kanopi secara keseluruhan', 'Fase pembungaan; penyebab berasal dari fase pelatihan sebelumnya', 'Sebagian area kanopi terlihat lebih tinggi/lebih dekat ke cahaya daripada area lain; awal pertumbuhan bunga tidak merata', 'Cabang tidak tersebar merata pada jaring SCRoG selama pelatihan; pembagian Mainlining asimetris dengan kekuatan tunas utama yang tidak seimbang; jaring/pengarahan tunas tidak dikoreksi selama pertumbuhan selanjutnya', ''),
  ('unregelmaessige-bewaesserung', 'Penyiraman tidak teratur', 'Masalah pengairan', 'Pergantian terus-menerus antara terlalu kering dan terlalu basah lebih menekan akar daripada kekurangan atau kelebihan air yang konsisten; gejalanya biasanya berubah-ubah dan tampak bertentangan.', 'Seluruh tanaman; akar', 'Semua fase', 'Daun berganti antara sedikit terkulai (terlalu kering) dan terkulai-mengilap (terlalu basah) sepanjang hari/antarwaktu siram; pertumbuhan tidak teratur dan tersendat', 'Tidak ada pola penyiraman tetap; menyiram “berdasarkan perasaan”, bukan pengukuran kelembapan substrat; ukuran pot terlalu besar dibandingkan tanaman sehingga pengeringannya tidak merata; beberapa orang menyiram tanpa koordinasi', 'https://plantclue.com/cannabis-richtig-giessen/'),
  ('unterwaesserung', 'Kekurangan air', 'Masalah pengairan', 'Penyiraman terlalu jarang atau terlalu sedikit membuat substrat kering dan daun layu/lemas; berbeda dari penyiraman berlebihan, daun tampak cepat pulih setelah disiram.', 'Seluruh tanaman', 'Semua fase', 'Daun terkulai dan lemas; substrat terasa kering hingga sangat kering; pot terasa sangat ringan saat diangkat', 'Penyiraman terlalu jarang atau terlalu sedikit; pot terlalu kecil dibandingkan ukuran tanaman (lihat [[wurzelverdichtung-topfgebunden]]); udara ruang sangat kering sehingga substrat lebih cepat mengering', 'https://plantclue.com/cannabis-richtig-giessen/; https://plantclue.com/cannabis-blaetter-rollen-sich-ein/'),
  ('verticillium-welke', 'Layu Verticillium', 'Penyakit / jamur', 'Penyakit jamur sistemik yang jarang tetapi agresif dan mirip layu Fusarium; cirinya layu progresif dari bawah ke atas, didahului perubahan warna daun bawah menjadi kekuningan-perunggu.', 'Jaringan pembuluh; mula-mula daun bawah, lalu menjalar ke atas', 'Semua fase', 'Daun paling bawah berubah kekuningan-perunggu sesaat sebelum layu', 'Infeksi jamur melalui substrat terkontaminasi, sering dari tanah/lokasi luar ruang yang sudah tercemar; patogen sangat tahan dan dapat bertahan lama di tanah', ''),
  ('vorzeitige-bluete-autoflower-stress', 'Pembungaan dini pada autoflower akibat stres', 'Masalah pembungaan/panen', 'Varietas autoflower berbunga berdasarkan umur, tetapi stres berat pada awal pertumbuhan (pemindahan pot, kesalahan pelatihan) dapat memicu pembungaan dini saat struktur tanaman masih lebih kecil.', 'Seluruh tanaman', 'Peralihan pertumbuhan vegetatif ke pembungaan pada autoflower', 'Tanda bunga pertama muncul jauh lebih awal daripada perkiraan deskripsi varietas; ukuran tanaman lebih kecil saat pembungaan dimulai', 'Syok transplantasi berat akibat pemindahan pot yang terlambat/kasar; pelatihan agresif (defoliasi berat, topping) terlalu dini pada fase pertumbuhan; akar rusak akibat hama atau luka mekanis', ''),
  ('vpd-zu-hoch', 'VPD terlalu tinggi', 'Suhu / kelembapan / VPD', 'Defisit tekanan uap (VPD) yang terlalu tinggi (misalnya suhu tinggi berpadu dengan kelembapan udara rendah) memaksa tanaman bertranspirasi berlebihan; terlihat sebagai ujung daun terbakar meski pemupukan tepat.', 'Ujung dan tepi daun; seluruh tanaman', 'Semua fase', 'Tepi daun sedikit melengkung ke atas (bentuk taco); ujung daun agak kering dan tampak runcing', 'Kombinasi suhu terlalu tinggi dan kelembapan relatif terlalu rendah; pengendalian iklim ruang tanam tidak ada atau disetel keliru', 'https://plantclue.com/luftfeuchtigkeit-cannabis-anbau/'),
  ('vpd-zu-niedrig', 'VPD terlalu rendah', 'Suhu / kelembapan / VPD', 'VPD terlalu rendah (misalnya kelembapan udara tinggi disertai suhu rendah) membuat stomata menutup; tanaman hampir tidak menyerap CO₂ sehingga pertumbuhan terhenti meski kondisi lain optimal.', 'Seluruh tanaman', 'Semua fase; kritis saat pembungaan (menambah risiko Botrytis)', 'Pertumbuhan umum melambat meski cahaya dan nutrisi optimal; daun tampak sedikit lemas/lembap tanpa benar-benar layu', 'Kelembapan relatif terlalu tinggi berpadu dengan suhu terlalu rendah; sirkulasi udara buruk menyebabkan kelembapan menumpuk di sekitar tanaman', 'https://plantclue.com/luftfeuchtigkeit-cannabis-anbau/'),
  ('wachstumsstagnation-sammeldiagnose', 'Pertumbuhan terhenti (diagnosis umum)', 'Masalah pertumbuhan dan pelatihan', 'Diagnosis awal umum untuk kondisi “tanaman tidak tumbuh” tanpa gejala tunggal yang langsung terlihat; berfungsi sebagai titik masuk wizard untuk mengarahkan ke diagnosis akar, cahaya, nutrisi, atau iklim yang lebih spesifik.', 'Seluruh tanaman', 'Semua fase', 'Pertumbuhan umum lebih lambat daripada perkiraan, tanpa gejala daun tertentu', 'Hampir SEMUA diagnosis lain dalam basis data ini dapat menjadi penyebab mendasar: akar sesak; lockout pH; kekurangan cahaya/etiolasi; kekurangan CO₂; kekurangan oksigen; kekurangan nutrisi pada tahap awal yang belum spesifik', 'https://plantclue.com/cannabis-wachstum-stagniert/'),
  ('wassertemperatur-stress', 'Stres suhu air', 'Masalah pengairan', 'Air siram terlalu dingin (langsung dari keran, di bawah 18 derajat) menekan akar dan dapat menimbulkan gabungan gejala stres dingin serta kekurangan fosfor, meski suhu ruang tidak bermasalah.', 'Akar; seluruh tanaman secara tidak langsung', 'Semua fase', 'Pertumbuhan sedikit melambat segera setelah disiram air dingin; kadang tangkai daun sedikit berubah ungu (penyerapan P berkurang saat dingin)', 'Air siram diambil langsung dari keran dingin tanpa dihangatkan; terutama pada musim dingin/suplai air dingin tanpa didiamkan hingga mencapai suhu ruang', 'https://plantclue.com/cannabis-richtig-giessen/'),
  ('weisse-fliegen', 'Kutu kebul', 'Hama', 'Serangga kecil putih mirip ngengat yang terbang berkelompok saat tanaman disentuh; kerusakan akibat isapan mirip kutu daun, tetapi perilaku terbang berkelompok merupakan ciri paling jelas.', 'Bagian bawah daun', 'Semua fase', 'Serangga putih kecil beterbangan berkelompok saat tanaman disentuh/digoyang; bintik kekuningan ringan di permukaan atas daun akibat isapan', 'Terbawa oleh tanaman terinfeksi; kondisi hangat mempercepat perkembangbiakan', 'https://plantclue.com/diagnose/schaedlinge/; https://plantclue.com/weisse-fliege-cannabis-bekaempfen/; https://plantclue.com/cannabis-krankheiten-erkennen/'),
  ('windbrand', 'Luka bakar angin', 'Stres lingkungan', 'Aliran udara langsung yang terlalu kuat (kipas dalam ruang atau angin luar ruang) menyebabkan stres pengeringan mekanis pada daun yang paling terpapar; tidak bergantung pada umur daun, berbeda dari kekurangan nutrisi.', 'Daun tepi yang terpapar, tanpa memandang usia', 'Semua fase', 'Tepi daun kering dan sedikit rapuh pada daun yang paling terpapar aliran udara', 'Kipas terlalu dekat dan diarahkan langsung ke tanaman (dalam ruang); angin kuat tanpa pelindung di lokasi budidaya (luar ruang)', 'https://plantclue.com/cannabis-windschaeden-symptome/; https://plantclue.com/cannabis-blattspitzen-braun/'),
  ('wollaeuse', 'Kutu putih', 'Hama', 'Serangga kecil menetap yang tertutup lapisan putih menyerupai lilin/kapas; sering berkumpul di ketiak daun dan buku batang.', 'Ketiak daun; buku batang; bagian bawah daun', 'Semua fase', 'Gumpalan kecil putih seperti kapas/wol di ketiak daun atau buku batang', 'Terbawa oleh tanaman terinfeksi; mikroiklim hangat dan agak terlindung (ketiak daun) mendukung keberadaannya', 'https://plantclue.com/wolllaeuse-cannabis-bekaempfen/'),
  ('wurzellaeuse', 'Kutu akar', 'Masalah akar', 'Hama yang mengisap cairan akar di dalam substrat; bagian atas tanaman menunjukkan penguningan menyebar dan layu yang menyerupai kekurangan nutrisi, tetapi tidak membaik setelah pemupukan.', 'Akar; seluruh tanaman (gejala lanjutan)', 'Semua fase', 'Daun tua sedikit menguning menyebar tanpa pola jelas; pertumbuhan sedikit melambat', 'Terbawa substrat terkontaminasi atau tanaman terinfeksi di dekatnya; kondisi yang mendukung (permukaan substrat hangat dan lembap) mempercepat perkembangbiakan', ''),
  ('wurzelverdichtung-topfgebunden', 'Akar sesak / tanaman terikat pot', 'Masalah akar', 'Tanaman tumbuh terlalu besar dibandingkan pot; akar melingkar di sepanjang tepi pot. Terlihat sebagai pertumbuhan terhenti meski perawatan tepat.', 'Akar; seluruh tanaman (dampak lanjutan)', 'Fase pertumbuhan vegetatif, terutama menjelang akhir masa vegetatif', 'Pertumbuhan melambat meski pemupukan dan penyiraman tepat; substrat mengering jauh lebih cepat dari biasanya setelah disiram', 'Pot terlalu kecil untuk ukuran/lama pertumbuhan tanaman; tidak dipindahkan ke pot lebih besar tepat waktu selama fase pertumbuhan', 'https://plantclue.com/cannabis-umtopfen/'),
  ('zinktoxizitaet', 'Toksisitas seng', 'Kelebihan nutrisi', 'Toksisitas sangat jarang akibat dosis yang sangat berlebihan; sering memicu kekurangan besi sekunder pada daun baru (antagonisme).', 'Daun baru', 'Fase pertumbuhan vegetatif', 'Klorosis antartulang daun pada daun baru, mirip kekurangan besi', 'Dosis sediaan seng atau campuran mikronutrien sangat berlebihan; penggunaan bahan galvanis dalam sistem pengairan (sangat jarang)', ''),
  ('zinkmangel', 'Kekurangan seng', 'Kekurangan nutrisi', 'Kekurangan mikronutrien yang tidak mudah berpindah, dengan ruas pendek, daun baru kecil dan berubah bentuk, serta klorosis antartulang daun di titik tumbuh.', 'Titik tumbuh baru; daun paling atas', 'Fase pertumbuhan vegetatif', 'Daun baru di ujung kecil dan sedikit berubah bentuk; area antar tulang daun pada pertumbuhan termuda agak pucat', 'pH terlalu tinggi menghambat penyerapan Zn; kelebihan fosfor menggeser seng; kekurangan Zn nyata dalam substrat sangat jarang', '')
